from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract each group of nested parentheses
    groups = []
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Separate each group into separate strings
    result = [group for group in groups if group]

    # Step 4: Ensure each group is balanced (each open brace is properly closed)
    balanced_groups = []

    for group in result:
        open_braces = 0
        is_balanced = True

        for char in group:
            if char == "(":
                open_braces += 1
            elif char == ")":
                open_braces -= 1

            if open_braces < 0:
                is_balanced = False
                break

        if is_balanced and open_braces == 0:
            balanced_groups.append(group)

    return balanced_groups

